def neighbor_count(seg,i,j):
    c=0
    for di in(-1,0,1):
        for dj in(-1,0,1):
            if (di,dj)!=(0,0) and 0<=i+di<4 and 0<=j+dj<4 and seg[i+di][j+dj]!=0: c+=1
    return c

def comp_sizes(seg):
    seen=set(); sizes={}
    for i in range(4):
        for j in range(4):
            if seg[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); n=0
                while st:
                    a,b=st.pop(); n+=1
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<4 and 0<=y<4 and seg[x][y] and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                sizes[(i,j)]=n
    return sizes

