def stats(seg):
    cells=[(i,j) for i in range(4) for j in range(4) if seg[i][j]]
    n=len(cells)
    # perimeter
    per=sum(4-sum(1 for di,dj in((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+di<4 and 0<=j+dj<4 and seg[i+di][j+dj]) for i,j in cells)
    # components
    seen=set(); comps=[]
    for c in cells:
        if c in seen: continue
        st=[c]; seen.add(c); k=0
        while st:
            a,b=st.pop(); k+=1
            for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+di,b+dj
                if 0<=x<4 and 0<=y<4 and seg[x][y] and (x,y) not in seen: seen.add((x,y)); st.append((x,y))
        comps.append(k)
    # 2x2 full blocks
    sq=sum(1 for i in range(3) for j in range(3) if all(seg[i+a][j+b] for a in(0,1) for b in(0,1)))
    # border cells
    bord=sum(1 for i,j in cells if i in(0,3) or j in(0,3))
    # h and v runs>=3 count
    def runs(lines):
        return sum(1 for L in lines for s in ''.join('1' if v else '0' for v in L).split('0') if len(s)>=3)
    r3=runs(seg)+runs([list(c) for c in zip(*seg)])
    return dict(n=n, per=per, comps=len(comps), maxc=max(comps), minc=min(comps), iso=sum(1 for c in comps if c==1), sq=sq, bord=bord, r3=r3)
