import itertools
def nb(seg,i,j,rad,mode):
    c=0
    for di in range(-rad,rad+1):
        for dj in range(-rad,rad+1):
            if mode=='orth' and abs(di)+abs(dj)!=1: continue
            if mode=='diag' and abs(di)!=1 or abs(dj)!=1: continue
            if di==0 and dj==0: continue
            x,y=i+di,j+dj
            if 0<=x<4 and 0<=y<4 and seg[x][y]: c+=1
    return c

def comp_at(seg,i,j):
    st=[(i,j)]; seen={(i,j)}; n=0
    while st:
        a,b=st.pop(); n+=1
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+di,b+dj
            if 0<=x<4 and 0<=y<4 and seg[x][y] and (x,y) not in seen: seen.add((x,y)); st.append((x,y))
    return n

