# scoring functions: f(segs,k,i,j) -> number; winner = min or max, tie-break by color max or min
def make_scores(segs,i,j):
    d={}
    for k in range(4):
        seg=segs[k]
        d[k]={
          'n': sum(v!=0 for r in seg for v in r),
          'orth': nb(seg,i,j,1,'orth'),
          'diag': sum(1 for di in(-1,1) for dj in(-1,1) if 0<=i+di<4 and 0<=j+dj<4 and seg[i+di][j+dj]),
          'box': nb(seg,i,j,1,'box'),
          'row': sum(v!=0 for v in seg[i]),
          'col': sum(seg[r][j]!=0 for r in range(4)),
          'comp': comp_at(seg,i,j) if seg[i][j] else None,
          'color': seg[i][j],
        }
    return d

feats=['n','orth','diag','box','row','col','comp','color']
found=[]
for feat,mm,tb in itertools.product(feats,['min','max'],['colormax','colormin']):
    good=True
    for name,i,j,cand,o in conf:
        sc=make_scores(segs_of(G[name+' input']),i,j)
        ks=[k for k,_ in cand]
        vals={k:sc[k][feat] for k in ks if sc[k][feat] is not None}
        best=(min(vals.values()) if mm=='min' else max(vals.values()))
        ws=[k for k in vals if vals[k]==best]
        if tb=='colormax': w=max(ws,key=lambda k:sc[k]['color'])
        else: w=min(ws,key=lambda k:sc[k]['color'])
        if sc[w]['color']!=o: good=False; break
    if good: found.append((feat,mm,tb))
print(found)

